require_once __DIR__ . '/../bootstrap.php'; require_admin();if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Method Not Allowed');}verify_csrf();$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);if(!$id){set_flash('error','ID người dùng không hợp lệ.');header('Location: '.admin_url('users/index.php'));exit;}try{$st=$conn->prepare("DELETE FROM users WHERE id=? AND role <> 'admin'");$st->execute([$id]);set_flash($st->rowCount()?'success':'warning',$st->rowCount()?'Đã xóa người dùng.':'Không thể xóa tài khoản này hoặc tài khoản không tồn tại.');}catch(PDOException $e){set_flash('error','Không thể xóa người dùng lúc này.');}header('Location: '.admin_url('users/index.php'));exit;
